#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#include<math.h>
#define D 768
#define H 12
#define L 12
#define V 50257
#define N 1024
#define F 3072
#define R 64
float*C,*W[L][12],*lb,*lg,*we,*pe,*x;
void ln(float*o,float*x,float*g,float*b){float m=0,v=0;
 for(int j=0;j<D;j++)m+=x[j];m/=D;
 for(int j=0;j<D;j++){float d=x[j]-m;v+=d*d;}
 v=sqrtf(v/D+1e-5f);for(int j=0;j<D;j++)o[j]=(x[j]-m)/v*g[j]+b[j];}
void mm(float*o,float*x,float*w,float*b,int d,int k){
 for(int j=0;j<d;j++){float s=b?b[j]:0;for(int p=0;p<k;p++)s+=x[p]*w[p*d+j];o[j]=s;}}
float nrm(float*x,int n){float s=0;for(int i=0;i<n;i++)s+=x[i]*x[i];return sqrtf(s);}
int main(){C=malloc(497759232);FILE*f=fopen("/app/gpt2-124M.ckpt","rb");fread(C,4,124439808,f);fclose(f);
 float*p=C;
 int order[]={0,1,10,11,2,3,4,5,6,7,8,9};
 for(int i=0;i<L;i++){int l=order[i];
  W[l][0]=p;p+=3*D;W[l][1]=p;p+=3*D*D;W[l][2]=p;p+=D;
  W[l][3]=p;p+=D*D;W[l][4]=p;p+=D;W[l][5]=p;p+=D;W[l][6]=p;p+=D;
  W[l][7]=p;p+=D;W[l][8]=p;p+=F;W[l][9]=p;p+=F*D;W[l][10]=p;p+=D;W[l][11]=p;p+=F*D;}
 lb=p;p+=D;lg=p;p+=D;we=p;p+=V*D;pe=p;
 float emb[D],xn[D],qkv[3*D],a[D],pr[D],x1[D],xn2[D],h[F],h2[D];
 for(int j=0;j<D;j++)emb[j]=we[464*D+j]+pe[j];
 printf("emb: |x|=%.3f mean=%.4f\n",nrm(emb,D),emb[0]);
 ln(xn,emb,W[0][5],W[0][4]);
 printf("xn(LN1): |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(xn,D),xn[0],xn[1],xn[2],xn[3]);
 mm(qkv,xn,W[0][1],W[0][0],3*D,D);
 printf("qkv: |x|=%.3f q0=%.4f k0=%.4f v0=%.4f\n",nrm(qkv,3*D),qkv[0],qkv[D],qkv[2*D]);
 // attention at pos 0: output = v
 memcpy(a,qkv+2*D,D*4);
 printf("attn_out(v): |x|=%.3f\n",nrm(a,D));
 mm(pr,a,W[0][3],W[0][2],D,D);
 printf("c_proj_out: |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(pr,D),pr[0],pr[1],pr[2],pr[3]);
 for(int j=0;j<D;j++)x1[j]=emb[j]+pr[j];
 printf("x1(emb+attn): |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(x1,D),x1[0],x1[1],x1[2],x1[3]);
 ln(xn2,x1,W[0][7],W[0][6]);
 printf("xn2(LN2): |x|=%.3f\n",nrm(xn2,D));
 mm(h,xn2,W[0][9],W[0][8],F,D);
 printf("c_fc_out: |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(h,F),h[0],h[1],h[2],h[3]);
 for(int j=0;j<F;j++){float t=h[j];h[j]=.5f*t*(1.f+tanhf(.7978845608f*(t+.044715f*t*t*t)));}
 printf("gelu_out: |x|=%.3f\n",nrm(h,F));
 mm(h2,h,W[0][11],W[0][10],D,F);
 printf("mlp_proj: |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(h2,D),h2[0],h2[1],h2[2],h2[3]);
 for(int j=0;j<D;j++)x1[j]+=h2[j];
 printf("x2(x1+mlp): |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(x1,D),x1[0],x1[1],x1[2],x1[3]);
 // Now test with transposed weights
 printf("\n--- Transposed ---\n");
 for(int j=0;j<D;j++)emb[j]=we[464*D+j]+pe[j];
 ln(xn,emb,W[0][5],W[0][4]);
 // transposed mm
 for(int j=0;j<3*D;j++){float s=W[0][0][j];for(int k=0;k<D;k++)s+=xn[k]*W[0][1][j*D+k];qkv[j]=s;}
 printf("qkv(T): |x|=%.3f q0=%.4f k0=%.4f v0=%.4f\n",nrm(qkv,3*D),qkv[0],qkv[D],qkv[2*D]);
 memcpy(a,qkv+2*D,D*4);
 for(int j=0;j<D;j++){float s=W[0][2][j];for(int k=0;k<D;k++)s+=a[k]*W[0][3][j*D+k];pr[j]=s;}
 printf("c_proj_out(T): |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(pr,D),pr[0],pr[1],pr[2],pr[3]);
 for(int j=0;j<D;j++)x1[j]=emb[j]+pr[j];
 printf("x1(T): |x|=%.3f\n",nrm(x1,D));
 ln(xn2,x1,W[0][7],W[0][6]);
 for(int j=0;j<F;j++){float s=W[0][8][j];for(int k=0;k<D;k++)s+=xn2[k]*W[0][9][j*D+k];h[j]=s;}
 printf("c_fc_out(T): |x|=%.3f\n",nrm(h,F));
 for(int j=0;j<F;j++){float t=h[j];h[j]=.5f*t*(1.f+tanhf(.7978845608f*(t+.044715f*t*t*t)));}
 for(int j=0;j<D;j++){float s=W[0][10][j];for(int k=0;k<F;k++)s+=h[k]*W[0][11][j*F+k];h2[j]=s;}
 printf("mlp_proj(T): |x|=%.3f\n",nrm(h2,D));
 for(int j=0;j<D;j++)x1[j]+=h2[j];
 printf("x2(T): |x|=%.3f first4=%.4f %.4f %.4f %.4f\n",nrm(x1,D),x1[0],x1[1],x1[2],x1[3]);
 return 0;}
